const ClickPipeSchema = z
  .object({
    id: z.uuid().exactOptional().openapi({ description: 'Unique ClickPipe ID.' }),
    serviceId: z
      .uuid()
      .exactOptional()
      .openapi({ description: 'ID of the service this ClickPipe belongs to.' }),
    name: z
      .string()
      .min(1)
      .max(255)
      .exactOptional()
      .openapi({ description: 'Name of the ClickPipe.', example: 'my_postgres_pipe' }),
    state: z
      .enum([
        'Unknown',
        'Provisioning',
        'Running',
        'Degraded',
        'Stopping',
        'Stopped',
        'Failed',
        'Completed',
        'InternalError',
        'Setup',
        'Snapshot',
        'Paused',
        'Pausing',
        'Modifying',
        'Resync',
      ])
      .exactOptional()
      .openapi({
        description:
          'Current lifecycle state of the ClickPipe. For database pipes: "Provisioning" (initial setup), "Setup" (configuring replication), "Snapshot" (initial data load), "Running" (actively replicating), "Pausing" (transitioning to paused state), "Paused" (temporarily paused), "Modifying" (applying configuration updates), "Resync" (swapping resync tables with original tables), "Failed" (error occurred), "Unknown". For streaming/object storage pipes (Kafka, Kinesis, S3): "Unknown" (initial state), "Provisioning" (setting up resources), "Running" (actively ingesting data), "Stopping" (transitioning to stopped state), "Stopped" (manually stopped, can be restarted), "Completed" (batch ingestion finished for object storage), "Failed" (error occurred, pipe stopped), "InternalError" (internal system error).',
        example: 'Running',
      }),
    scaling: ClickPipeScalingSchema.exactOptional(),
    source: ClickPipeSourceSchema.exactOptional(),
    destination: ClickPipeDestinationSchema.exactOptional(),
    fieldMappings: z
      .array(ClickPipeFieldMappingSchema)
      .exactOptional()
      .openapi({
        description:
          'Field mappings of the ClickPipe. Note that all destination columns must be included in the mappings.',
      }),
    settings: ClickPipeSettingsSchema.exactOptional(),
    createdAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Creation timestamp of the ClickPipe in ISO 8601 format.' }),
    updatedAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Last update timestamp of the ClickPipe in ISO 8601 format.' }),
  })
  .openapi({ required: [] })
  .openapi('ClickPipe')

