const PgHaTypeSchema = z
  .enum(['none', 'async', 'sync'])
  .openapi({
    description:
      'Type of high availability: “none” for no replication, “async” for asynchronous replication to a single standby, and “sync” for synchronous replication to two standbys.',
  })
  .openapi('PgHaType')

const PgProviderSchema = z
  .enum(['aws', 'gcp'])
  .openapi({ title: 'Cloud provider', description: 'The cloud provider for a Postgres service.' })
  .openapi('PgProvider')

const PgRegionSchema = z
  .string()
  .openapi({ title: 'Service region', description: 'The cloud region for a Postgres service.' })
  .openapi('PgRegion')

const PgVersionSchema = z
  .enum(['18', '17'])
  .openapi({ title: 'Postgres major version' })
  .openapi('PgVersion')

const PgTagsSchema = z
  .array(ResourceTagsV1Schema)
  .max(50)
  .openapi({
    title: 'Postgres Tags',
    description:
      'Tags associated with the Postgres service. Tag keys starting with “chc_” are reserved for internal use.',
  })
  .openapi('PgTags')

const PgNamePropertySchema = z
  .string()
  .min(1)
  .max(50)
  .openapi({
    title: 'Postgres Service Name',
    description:
      'Name of the Postgres service. Alphanumerical string with whitespaces up to 50 characters.',
  })
  .openapi('PgNameProperty')

const PgIdPropertySchema = z
  .uuid()
  .openapi({ title: 'Unique Postgres service ID', example: 'f71df78e-ddad-82d0-8dfa-abbec741b82e' })
  .openapi('PgIdProperty')

const PgStatePropertySchema = z
  .enum([
    'creating',
    'restarting',
    'running',
    'replaying_wal',
    'restoring_backup',
    'finalizing_restore',
    'unavailable',
    'stopped',
    'deleting',
  ])
  .openapi({ title: 'Postgres Service State', description: 'Current state of the service' })
  .openapi('PgStateProperty')

const PgIsPrimaryPropertySchema = z
  .boolean()
  .default(false)
  .openapi({
    title: 'Postgres Service is Primary',
    description: 'True if this service is the primary service in the data warehouse',
  })
  .openapi('PgIsPrimaryProperty')

const PgCreatedAtPropertySchema = z.iso
  .datetime({ offset: true })
  .openapi({ title: 'Postgres Service creation timestamp', example: '2026-03-26T20:51:16.384Z' })
  .openapi('PgCreatedAtProperty')

const BasePostgresServiceSchema = z
  .object({
    name: PgNamePropertySchema.exactOptional(),
    provider: PgProviderSchema.exactOptional(),
    region: PgRegionSchema.exactOptional(),
    postgresVersion: PgVersionSchema.exactOptional(),
    size: PgSizeSchema.exactOptional(),
    haType: PgHaTypeSchema.exactOptional(),
    tags: PgTagsSchema.exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('BasePostgresService')

const PostgresServiceSchema = z
  .object({
    name: PgNamePropertySchema.exactOptional(),
    provider: PgProviderSchema.exactOptional(),
    region: PgRegionSchema.exactOptional(),
    postgresVersion: PgVersionSchema.exactOptional(),
    size: PgSizeSchema.exactOptional(),
    haType: PgHaTypeSchema.exactOptional(),
    tags: PgTagsSchema.exactOptional(),
    ipAccessList: z
      .array(PostgresIpAccessListEntrySchema)
      .exactOptional()
      .openapi({
        description:
          'IPv4 access rules shown in the console. IPv6 rules are not included. Returned when reading or configuring access; omitted from other service updates.',
      }),
    id: PgIdPropertySchema.exactOptional(),
    storageSize: PgStorageSizeSchema.exactOptional(),
    state: PgStatePropertySchema.exactOptional(),
    createdAt: PgCreatedAtPropertySchema.exactOptional(),
    isPrimary: PgIsPrimaryPropertySchema.exactOptional(),
    connectionString: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Connection string to the Postgres service. Embeds the service password, so it is only returned when the service is created or its password is reset. Omitted from every other response when Postgres credential redaction is enabled for the organization. Not guaranteed to be present — treat as optional.',
      }),
    username: z
      .string()
      .exactOptional()
      .openapi({ description: 'Username for the Postgres service' }),
    password: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Password for the Postgres service. Only returned when the service is created or its password is reset. Omitted from every other response when Postgres credential redaction is enabled for the organization. Not guaranteed to be present — treat as optional.',
      }),
    hostname: z
      .string()
      .exactOptional()
      .openapi({ description: 'Hostname for the Postgres service' }),
    earliestRestoreTime: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Earliest point in time the service can be restored to with the restore endpoint. ISO-8601. Only present for a primary service once its first backup has completed.',
      }),
  })
  .openapi({ required: [] })
  .openapi('PostgresService')

const PostgresServicePostRequestSchema = z
  .object({
    name: PgNamePropertySchema,
    provider: PgProviderSchema,
    region: PgRegionSchema,
    postgresVersion: PgVersionSchema.exactOptional(),
    size: PgSizeSchema,
    haType: PgHaTypeSchema.exactOptional(),
    tags: PgTagsSchema.exactOptional(),
    ipAccessList: z
      .array(PostgresIpAccessListEntrySchema)
      .exactOptional()
      .openapi({
        description:
          'IPv4 TCP access rules to apply when creating the service. Omit to allow all IPv4 and IPv6 addresses on Postgres (5432) and PgBouncer (6432). Provide an empty list to block public access. When provided, only these rules are allowed; include separate rules for each required port.',
      }),
    pgConfig: PgConfigSchema.exactOptional(),
    pgBouncerConfig: PgBouncerConfigSchema.exactOptional(),
  })
  .openapi({ required: ['name', 'provider', 'region', 'size'] })
  .openapi('PostgresServicePostRequest')

const PostgresServicePatchRequestSchema = z
  .object({
    ipAccessList: PostgresIpAccessListPatchSchema.exactOptional(),
    name: PgNamePropertySchema.exactOptional(),
    size: PgSizeSchema.exactOptional(),
    haType: PgHaTypeSchema.exactOptional(),
    tags: PgTagsSchema.exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('PostgresServicePatchRequest')

const PgPitrRestoreTargetPropertySchema = z.iso
  .datetime({ offset: true })
  .openapi({
    title: 'PITR Restore Target as an RFC 3339-formatted timestamp in UTC time.',
    example: '2026-03-31T18:17:37Z',
    description:
      'The point in time at which to recover, as either date/time, named restore point, or a specific transaction ID.',
  })
  .openapi('PgPitrRestoreTargetProperty')

const PgPasswordSchema = z
  .unknown()
  .superRefine((val, ctx) => {
    if (typeof val === 'string') {
      if (!new RegExp('[a-z]').test(val)) {
        ctx.addIssue({ code: 'custom' })
      }
    }
  })
  .and(
    z.unknown().superRefine((val, ctx) => {
      if (typeof val === 'string') {
        if (!new RegExp('[A-Z]').test(val)) {
          ctx.addIssue({ code: 'custom' })
        }
      }
    }),
  )
  .and(
    z.unknown().superRefine((val, ctx) => {
      if (typeof val === 'string') {
        if (!new RegExp('[0-9]').test(val)) {
          ctx.addIssue({ code: 'custom' })
        }
      }
    }),
  )
  .openapi({
    title: 'Password',
    description:
      'Optional password. If not provided a new password is generated and provided in the response. Must contain:\n\n* At least one lowercase letter\n* At least one uppercase letter\n* At least one digit\n',
  })
  .openapi('PgPassword')

const PostgresServiceRestoreRequestSchema = z
  .object({
    name: PgNamePropertySchema,
    restoreTarget: PgPitrRestoreTargetPropertySchema,
    pgConfig: PgConfigSchema.exactOptional(),
    pgBouncerConfig: PgBouncerConfigSchema.exactOptional(),
    tags: PgTagsSchema.exactOptional(),
  })
  .openapi({ required: ['name', 'restoreTarget'] })
  .openapi('PostgresServiceRestoreRequest')

const PostgresServiceSetPasswordSchema = z
