export const getV1OrganizationsRoute = createRoute({
  method: 'get',
  path: '/v1/organizations',
  tags: ['Organization'],
  summary: 'Get list of available organizations',
  description:
    'Returns the organizations available to the caller, oldest first. An API key resolves to the single organization it belongs to; a user token returns every organization the user is a member of. Results are capped at `limit` (default 250) per page; the server may return fewer and caps the value at its own maximum. Every response carries `limit` and `nextCursor`; pass `nextCursor` as the `cursor` query parameter to fetch the next page, repeating until it is null.',
  operationId: 'organizationGetList',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(250)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'limit',
            description: 'Maximum number of results to return.',
            schema: { type: 'integer', minimum: 1, default: 250 },
            required: false,
          },
        }),
      cursor: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'cursor',
            description:
              "Opaque cursor from a previous response's `nextCursor`, marking where to resume the list.",
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: z
            .object({
              status: z
                .number()
                .exactOptional()
                .openapi({ description: 'HTTP status code.', example: 200 }),
              requestId: z
                .uuid()
                .exactOptional()
                .openapi({ description: 'Unique id assigned to every request. UUIDv4' }),
              result: z.array(OrganizationSchema).exactOptional(),
              limit: z
                .int()
                .exactOptional()
                .openapi({ description: 'Maximum number of results returned in this page.' }),
              nextCursor: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'Cursor for the next page, to be sent as the `cursor` query parameter. Null on the last page.',
                }),
            })
            .openapi({ required: [] }),
        },
      },
    },
    400: {
      description:
        'The request cannot be processed due to a client error. Please verify your request parameters and try again.',
      content: {
        'application/json': {
          schema: z
            .object({
              status: z
                .number()
                .exactOptional()
                .openapi({ description: 'HTTP status code.', example: 400 }),
              error: z
                .string()
                .exactOptional()
                .openapi({ description: 'Detailed error description.' }),
              requestId: z
                .uuid()
                .exactOptional()
                .openapi({ description: 'Unique id assigned to every request. UUIDv4' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
    500: {
      description:
        'An internal server error has occurred. If this issue persists, please contact ClickHouse Cloud support for assistance.',
      content: {
        'application/json': {
          schema: z
            .object({
              status: z
                .int()
                .exactOptional()
                .openapi({ description: 'HTTP status code.', example: 500 }),
              error: z
                .string()
                .exactOptional()
                .openapi({ description: 'Detailed error description.' }),
              requestId: z
                .uuid()
                .exactOptional()
                .openapi({ description: 'Unique id assigned to every request. UUIDv4' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
})

